<template>
  <div class="app-container operations">
    <div class="heading"><div><h2>任务中心</h2><p>查看进度、处理异常。读取用户正文和图片需要指定资源授权。</p></div><el-button v-if="has('podAdmin:privacy:grant')" :disabled="!!pending" @click="open('private.grant')">新增私有访问授权</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <el-alert v-if="pending" title="有一项操作结果待核对" type="warning" :closable="false"><p>{{ pending.requestId }}；只保存编号，不保存原因或用户正文。</p><el-button :loading="saving" @click="checkPending">核对原操作</el-button><el-button :disabled="saving" @click="recover">重填原操作</el-button></el-alert>
    <el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane label="运行任务" name="runs"/><el-tab-pane label="批量派发" name="batches"/><el-tab-pane v-if="has('podAdmin:privacy:grant')" label="私有访问授权" name="private-grants"/></el-tabs>
    <el-form v-if="tab !== 'private-grants'" inline class="query" @submit.prevent="search">
      <el-form-item label="日期"><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /></el-form-item><el-form-item label="用户 ID"><el-input v-model="query.userId" clearable inputmode="numeric" style="width:120px" /></el-form-item><el-form-item label="模型 ID"><el-input v-model="query.modelId" clearable inputmode="numeric" style="width:120px" /></el-form-item>
      <el-form-item label="状态"><el-select v-model="query.state" clearable style="width:140px"><el-option v-for="(label,value) in stateOptions" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item><el-button type="primary" :loading="loading" @click="search">查询</el-button></el-form-item>
    </el-form>
    <el-table v-loading="loading" :data="rows" empty-text="当前条件下没有记录">
      <template v-if="tab === 'private-grants'">
        <el-table-column prop="grantId" label="授权 ID" width="90"/><el-table-column prop="operatorUserId" label="操作员 ID" width="110"/><el-table-column prop="ownerUserId" label="所有者 ID" width="110"/><el-table-column label="授权资源" min-width="140"><template #default="{row}">{{ row.resourceType === 'run' ? '运行' : '素材' }} #{{ row.resourceId }}</template></el-table-column><el-table-column prop="purpose" label="用途" min-width="170" show-overflow-tooltip/><el-table-column prop="expiresAt" label="到期时间" min-width="185"/><el-table-column label="状态" width="95"><template #default="{row}">{{ row.revoked ? '已撤销' : new Date(row.expiresAt) <= new Date() ? '已到期' : '有效' }}</template></el-table-column>
        <el-table-column label="操作" min-width="160"><template #default="{row}"><el-button v-if="has('podAdmin:private:read')" link @click="readPrivate(row.resourceId,row.resourceType)">读取授权资源</el-button><el-button link type="danger" :disabled="row.revoked || !!pending" @click="open('private.revoke',row)">撤销</el-button></template></el-table-column>
      </template>
      <template v-else><el-table-column label="编号" width="100"><template #default="{row}">#{{ row.runId || row.batchId }}</template></el-table-column><el-table-column prop="userId" label="用户 ID" width="110"/><el-table-column prop="executionMode" label="执行模式" min-width="115"/><el-table-column v-if="tab === 'runs'" prop="mode" label="范围" min-width="100"/><el-table-column label="状态" min-width="120"><template #default="{row}"><el-tag :type="row.state === 'succeeded' ? 'success' : 'info'">{{ taskStates[row.state] || row.state }}</el-tag></template></el-table-column><el-table-column prop="createTime" label="创建时间" min-width="165"/>
        <el-table-column label="操作" min-width="230"><template #default="{row}"><el-button v-if="has('podAdmin:task:query')" link type="primary" @click="show(row)">详情</el-button><el-button v-if="has('podAdmin:task:cancel')" link type="danger" :disabled="!!pending" @click="open(tab === 'runs' ? 'task.cancel' : 'batch.stop',row)">{{ tab === 'runs' ? '取消运行' : '停止待派发' }}</el-button><el-button v-if="tab === 'runs' && has('podAdmin:private:read')" link @click="readPrivate(row.runId,'run')">授权内容</el-button></template></el-table-column>
      </template>
    </el-table><pagination v-show="total > 0" v-model:page="page" v-model:limit="size" :total="total" @pagination="load"/>
    <el-dialog v-model="dialog" :title="operationTitle" width="580px" :close-on-click-modal="false"><el-form label-width="110px" @submit.prevent>
      <template v-if="op === 'private.grant'"><el-form-item label="操作员 ID" required><el-input v-model="form.operatorUserId" inputmode="numeric"/></el-form-item><el-form-item label="所有者 ID" required><el-input v-model="form.ownerUserId" inputmode="numeric"/></el-form-item><el-form-item label="资源类型"><el-select v-model="form.resourceType"><el-option label="单个运行" value="run"/><el-option label="单个素材" value="asset"/></el-select></el-form-item><el-form-item label="资源 ID" required><el-input v-model="form.resourceId" inputmode="numeric"/></el-form-item><el-form-item label="到期时间" required><el-date-picker v-model="form.expiresAt" type="datetime" placeholder="最多 24 小时"/></el-form-item><p>操作员还须拥有私有读取权限，运行授权不会自动授权图片。</p></template>
      <el-alert v-else :title="op === 'task.cancel' ? '取消尚未执行的步骤；已提交调用继续核对，不清除未知预占。' : op === 'batch.stop' ? '只停止尚未派发的项，已派发运行需单独取消。' : '撤销后，后续读取立即重新校验。'" type="warning" :closable="false"/><el-form-item label="操作原因" required><el-input v-model="form.reason" maxlength="200" /></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="dialog=false">关闭</el-button><el-button type="primary" :loading="saving" @click="submit">确认</el-button></template></el-dialog>
    <el-dialog v-model="detailOpen" title="任务元信息" width="860px"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="编号">{{ detail.runId || detail.batch?.batchId }}</el-descriptions-item><el-descriptions-item label="状态">{{ taskStates[detail.state || detail.batch?.state] }}</el-descriptions-item></el-descriptions><el-table :data="nodes"><el-table-column prop="nodeId" label="节点"/><el-table-column prop="itemNo" label="批次项"/><el-table-column prop="nodeType" label="类型"/><el-table-column prop="modelId" label="模型 ID"/><el-table-column prop="state" label="状态"/><el-table-column prop="errorCode" label="安全错误码"/></el-table><pagination v-if="nodeTotal>10" v-model:page="nodePage" v-model:limit="nodeSize" :total="nodeTotal" @pagination="loadNodes"/></template></el-dialog>
    <el-dialog v-model="privateOpen" title="已授权的私有内容" width="860px" destroy-on-close @closed="clearPrivate"><el-alert title="本次读取已记录审计，请仅用于授权用途。" type="warning" :closable="false"/><el-alert v-if="privateError" :title="privateError" type="error" :closable="false"/><img v-if="privateImage" :src="privateImage" alt="授权的私有图片" class="private-image"/><pre v-if="privateContent" class="private-content">{{ JSON.stringify(privateContent,null,2) }}</pre></el-dialog>
  </div>
</template>
<script setup>
import{computed,onMounted,onBeforeUnmount,reactive,ref}from'vue'
import{ElMessage}from'element-plus'
import useUserStore from'@/store/modules/user'
import{adminList,adminGet,adminFile,catalogWrite,catalogAction}from'@/api/pod/admin'
import{localDate}from'@/utils/pod-admin'
import{operationPayload,operationMetadata,taskStates}from'@/utils/pod-operations'
const user=useUserStore(),has=p=>user.podAdmin?.permissions?.includes(p),tab=ref('runs'),rows=ref([]),total=ref(0),page=ref(1),size=ref(10),loading=ref(false),error=ref('')
const dates=ref([localDate(new Date(Date.now()-6*86400000)),localDate(new Date())]),query=reactive({userId:'',modelId:'',state:''}),stateOptions=computed(()=>Object.fromEntries(Object.entries(taskStates).filter(([k])=>tab.value==='runs'?!['active','stopped','completed'].includes(k):['active','stopped','completed'].includes(k))))
let sequence=0,detailSequence=0,privateSequence=0
const dialog=ref(false),op=ref(''),form=reactive({}),saving=ref(false),pending=ref(null),pendingKey=`pod-admin.operation:${user.id}`
const operationTitle=computed(()=>({'task.cancel':'取消运行','batch.stop':'停止待派发项','private.grant':'新增指定资源授权','private.revoke':'撤销授权'})[op.value])
function savePending(){if(pending.value)sessionStorage.setItem(pendingKey,JSON.stringify(pending.value));else sessionStorage.removeItem(pendingKey)}
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const result=await adminList(tab.value,{...query,beginDate:dates.value?.[0],endDate:dates.value?.[1],pageNum:page.value,pageSize:size.value});if(seq===sequence){rows.value=result.rows;total.value=result.total}}catch(e){if(seq===sequence)error.value=e.message}finally{if(seq===sequence)loading.value=false}}
function search(){page.value=1;load()}function changeTab(){query.state='';rows.value=[];search()}
function open(value,row={}){if(pending.value)return;op.value=value;Object.assign(form,{id:row.runId||row.batchId||row.grantId||'',revision:row.revision||'',operatorUserId:'',ownerUserId:row.userId||'',resourceId:row.runId||'',resourceType:'run',expiresAt:new Date(Date.now()+3600000),reason:''});dialog.value=true}
async function submit(){if(saving.value)return;if(pending.value&&pending.value.op!==op.value){error.value='请先核对原操作';return;}saving.value=true;error.value='';try{const payload=operationPayload(op.value,form);if(!pending.value){pending.value=operationMetadata(op.value,form);savePending()};await catalogWrite('POST',payload.path,{...payload.data,requestId:pending.value.requestId});pending.value=null;savePending();dialog.value=false;ElMessage.success('操作已完成');await load()}catch(e){error.value=e.message;if(e.code===400||e.code===403||e.code===404){pending.value=null;savePending()}}finally{saving.value=false}}
async function checkPending(){saving.value=true;try{await catalogAction(pending.value.requestId);pending.value=null;savePending();ElMessage.success('原操作已完成');load()}catch(e){error.value=e.message}finally{saving.value=false}}
function recover(){op.value=pending.value.op;Object.assign(form,{id:pending.value.id,revision:pending.value.revision,reason:'',operatorUserId:pending.value.operatorUserId||'',ownerUserId:pending.value.ownerUserId||'',resourceType:pending.value.resourceType||'run',resourceId:pending.value.resourceId||'',expiresAt:pending.value.expiresAt||null});dialog.value=true}
const detailOpen=ref(false),detail=ref(null),detailError=ref(''),nodes=ref([]),nodeTotal=ref(0),nodePage=ref(1),nodeSize=ref(10)
async function show(row){const seq=++detailSequence;detailOpen.value=true;detail.value=null;nodes.value=[];detailError.value='';nodePage.value=1;try{const r=await adminGet(`${tab.value}/${row.runId||row.batchId}`);if(seq!==detailSequence)return;detail.value=r.data;if(tab.value==='batches'){nodes.value=r.data.items;nodeTotal.value=nodes.value.length}else await loadNodes()}catch(e){if(seq===detailSequence)detailError.value=e.message}}
async function loadNodes(){const seq=detailSequence;try{const r=await adminList(`runs/${detail.value.runId}/nodes`,{pageNum:nodePage.value,pageSize:nodeSize.value});if(seq===detailSequence){nodes.value=r.rows;nodeTotal.value=r.total}}catch(e){if(seq===detailSequence)detailError.value=e.message}}
const privateOpen=ref(false),privateContent=ref(null),privateError=ref(''),privateImage=ref('')
function clearPrivate(){++privateSequence;privateContent.value=null;privateError.value='';if(privateImage.value)URL.revokeObjectURL(privateImage.value);privateImage.value=''}
async function readPrivate(id,kind){clearPrivate();const seq=privateSequence;privateOpen.value=true;try{if(kind==='asset'){const blob=await adminFile(`private/assets/${id}/content?variant=original`);if(seq===privateSequence&&privateOpen.value)privateImage.value=URL.createObjectURL(blob)}else{const r=await adminGet(`private/runs/${id}`);if(seq===privateSequence&&privateOpen.value)privateContent.value=r.data}}catch(e){if(seq===privateSequence)privateError.value=e.message}}
onMounted(()=>{try{const raw=sessionStorage.getItem(pendingKey);if(raw){const p=JSON.parse(raw);if(['task.cancel','batch.stop','private.grant','private.revoke'].includes(p.op)&&/^[0-9a-f-]{36}$/.test(p.requestId))pending.value=p;else error.value='操作编号记录无效，请核对审计'}}catch{error.value='无法读取待核对操作'};load()})
onBeforeUnmount(()=>{++sequence;++detailSequence;clearPrivate()})
</script>
<style scoped>.heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.heading h2{margin:0 0 8px}.heading p{color:var(--el-text-color-secondary)}.query :deep(.el-form-item){margin-bottom:12px}.operations :deep(.el-alert){margin:12px 0}.private-content{white-space:pre-wrap;overflow-wrap:anywhere;max-height:55vh;overflow:auto;padding:16px;background:var(--el-fill-color-light)}.private-image{max-width:100%;max-height:60vh;object-fit:contain}@media(max-width:700px){.heading{align-items:flex-start;flex-direction:column}.query :deep(.el-date-editor){width:100%}}</style>
